import { test, expect } from '@playwright/test';

test.describe('Async Form Submission - Submit Button Disabled State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><body><form id="testForm"><input type="text" id="name" placeholder="Enter name" required /><input type="email" id="email" placeholder="Enter email" required /><button type="submit">Submit</button></form><div id="result"></div><script>document.getElementById("testForm").addEventListener("submit", async (e) => { e.preventDefault(); const btn = e.target.querySelector("button"); btn.disabled = true; btn.textContent = "Submitting..."; try { await new Promise(resolve => setTimeout(resolve, 2000)); document.getElementById("result").textContent = "Form submitted successfully"; btn.textContent = "Submit"; } catch (err) { document.getElementById("result").textContent = "Error: " + err.message; btn.textContent = "Submit"; } finally { btn.disabled = false; } }); </script></body></html>');
  });

  test('should disable submit button when form is submitted', async ({ page }) => {
    const nameInput = page.getByLabel('');
    const emailInput = page.getByLabel('');
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await page.fill('#name', 'John Doe');
    await page.fill('#email', 'john@example.com');

    await submitButton.click();

    await expect(submitButton).toBeDisabled();
    await expect(submitButton).toContainText('Submitting...');
  });

  test('should re-enable submit button after async operation completes', async ({ page }) => {
    const submitButton = page.getByRole('button', { name: 'Submit' });
    const resultDiv = page.locator('#result');

    await page.fill('#name', 'Jane Smith');
    await page.fill('#email', 'jane@example.com');

    await submitButton.click();

    await expect(submitButton).toBeDisabled();

    await page.waitForTimeout(2500);

    await expect(submitButton).toBeEnabled();
    await expect(submitButton).toContainText('Submit');
    await expect(resultDiv).toContainText('Form submitted successfully');
  });

  test('should maintain button disabled state during entire async operation', async ({ page }) => {
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await page.fill('#name', 'Test User');
    await page.fill('#email', 'test@example.com');

    await submitButton.click();

    await expect(submitButton).toBeDisabled();

    await page.waitForTimeout(1000);
    await expect(submitButton).toBeDisabled();

    await page.waitForTimeout(1500);
    await expect(submitButton).toBeEnabled();
  });

  test('should prevent multiple form submissions while async operation is pending', async ({ page }) => {
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await page.fill('#name', 'Multiple Submit Test');
    await page.fill('#email', 'multi@example.com');

    await submitButton.click();

    await expect(submitButton).toBeDisabled();

    const clickAttempt = submitButton.click();
    await expect(submitButton).toBeDisabled();

    await page.waitForTimeout(2500);

    await expect(submitButton).toBeEnabled();
  });

  test('should update button text during async operation and restore after completion', async ({ page }) => {
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await page.fill('#name', 'Text Update Test');
    await page.fill('#email', 'text@example.com');

    const initialText = await submitButton.textContent();
    expect(initialText).toBe('Submit');

    await submitButton.click();

    const submittingText = await submitButton.textContent();
    expect(submittingText).toBe('Submitting...');

    await page.waitForTimeout(2500);

    const finalText = await submitButton.textContent();
    expect(finalText).toBe('Submit');
  });

  test('should handle form validation before disabling button', async ({ page }) => {
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await submitButton.click();

    await expect(submitButton).toBeEnabled();
  });

  test('should display success message after async form submission completes', async ({ page }) => {
    const submitButton = page.getByRole('button', { name: 'Submit' });
    const resultDiv = page.locator('#result');

    await page.fill('#name', 'Success Test');
    await page.fill('#email', 'success@example.com');

    await expect(resultDiv).toBeEmpty();

    await submitButton.click();

    await page.waitForTimeout(2500);

    await expect(resultDiv).toContainText('Form submitted successfully');
    await expect(submitButton).toBeEnabled();
  });
});
